/// <summary>
/// Extension of <c>TAMRebateCreateTransService</c> to add MET processing
/// metrics and execution tracing around rebate transaction creation.
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateTransService))]
internal final class METTAMRebateCreateTransService_Extension
{
}

Method.Source:
/// <summary>
/// Wraps the base <c>process</c> method to include MET metrics tracking
/// and execution tracing for rebate transaction creation.
/// </summary>
public void process(TAMRebateCreateTransContract _contract)
{
    METProcMetrics procMetrics   = METProcMetrics::construct(METBatchLogOperation::TAMCustVendRebateCreate);

    if (procMetrics)
    {
        procMetrics.setDescription(2, 'Process Started');
    }

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        next process(_contract);

        if (procMetrics)
        {
            procMetrics.endTrace();
        }
    }
}
